UPDATE point_template
SET is_deleted = 1
WHERE point_tmpl_id = #{pointTmplId}

UPDATE point_template
SET is_deleted = 0, update_time = NOW()
WHERE point_tmpl_id = #{pointTmplId}

UPDATE point_template
SET alarm_code = #{alarmCode}, update_time = NOW()
WHERE point_tmpl_id = #{pointTmplId}

UPDATE point_template SET alarm_code = CASE point_tmpl_id
WHEN #{point.pointTmplId} THEN #{point.alarmCode}
END, update_time = NOW() WHERE point_tmpl_id IN
#{point.pointTmplId}
